(6273520, 927874, 108069, '<td valign="top">Well done. Great lighting and perfect product shot (for a suspension company!).</td>', 'Well done. Great lighting and perfect product shot (for a suspension company!).', '2011-01-06 13:58:40.000000', NULL, 1),
