(6278762, 926722, 100831, '<td valign="top">beautiful warm, still life but I don''t really think of this as bits and pieces.</td>', 'beautiful warm, still life but I don''t really think of this as bits and pieces.', '2011-01-10 08:52:17.000000', NULL, 0),
(6278763, 927847, 113245, '<td valign="top">I''m with h2 on the sharpening, but the composition definitely draws you in. This loses something due to the DPC 800 pixel limit. It would really be cool on a wall sized at around four feet or so. Kinda cries out for life sized presentation. Speaking of which, a photographer I took a workshop from in ''08 at Zion National Park, Alain Briot, said the way he''ll spin some objectivity into judging his own photos is to hang one up on his wall and see how long he can live with it. If he can go a month having it staring back at him without taking it down, he figures it''s acceptable. That seemed like a good suggestion. Anyway, it stuck with me. It may have some bearing on your "couldn''t see the woods for the trees" (pun intended??) note regarding editing your "Winter Wonderland". That''s a beautiful image, Fred. A well deserved 1st place.</td>', 'I''m with h2 on the sharpening, but the composition definitely draws you in. This loses something due to the DPC 800 pixel limit. It would really be cool on a wall sized at around four feet or so. Kinda cries out for life sized presentation. Speaking of which, a photographer I took a workshop from in ''08 at Zion National Park, Alain Briot, said the way he''ll spin some objectivity into judging his own photos is to hang one up on his wall and see how long he can live with it. If he can go a month having it staring back at him without taking it down, he figures it''s acceptable. That seemed like a good suggestion. Anyway, it stuck with me. It may have some bearing on your "couldn''t see the woods for the trees" (pun intended??) note regarding editing your "Winter Wonderland". That''s a beautiful image, Fred. A well deserved 1st place.', '2011-01-10 08:53:26.000000', NULL, 0),
(6278780, 927676, 16148, '<td valign="top">Congratulations and well done!</td>', 'Congratulations and well done!', '2011-01-10 09:18:32.000000', NULL, 0),
